  const tombstone = await db.execute({ sql: "SELECT account_id FROM codex_cleanup_tombstones WHERE workspace_id=? AND auth_file=? LIMIT 1", args: [workspaceId, authFile] });
  if (!tombstone.rows[0]) return await operation();
