export async function submitCodexCallback(workspaceId: string, loginId: string, redirectUrl: string): Promise<void> { return await codexMutation(async () => { const login = await getLogin(workspaceId, loginId); let url: URL; try { url = new URL(redirectUrl); } catch { throw new CodexError("Paste the complete localhost callback URL from your browser."); } if (url.protocol !== "http:" || url.hostname !== "localhost" || url.port !== "1455" || url.pathname !== "/auth/callback") throw new CodexError("Callback URL must start with http://localhost:1455/auth/callback."); if (url.searchParams.get("state") !== login.state) throw new CodexError("Callback URL does not match this Codex login."); const code = url.searchParams.get("code")?.trim(); const error = url.searchParams.get("error")?.trim() || url.searchParams.get("error_description")?.trim(); if (!code && !error) throw new CodexError("Callback URL has no authorization code."); const { response } = await managementJson("/v0/management/oauth-callback", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ provider: "codex", state: login.state, ...(code ? { code } : { error }) }) }); if (!response.ok) throw new CodexError("CLIProxy rejected the Codex callback.", 502); }); }
