export async function cancelCodexLogin(workspaceId: string, loginId: string): Promise<void> { return await codexMutation(async () => { const login = await getLogin(workspaceId, loginId).catch((error) => { if (error instanceof CodexError && error.status === 410) return undefined; throw error; }); if (!login) return; try { await cancelRemote(login.state); } finally { await finishLogin(login); } }); }
