export async function invalidateCodexQuota(workspaceId: string, id: string): Promise<void> { await db.execute({ sql: "DELETE FROM codex_quota_cache WHERE workspace_id=? AND account_id=?", args: [workspaceId, id] }); }
export async function redeemCodexCredit(workspaceId: string, id: string, confirmation: unknown): Promise<void> { if (typeof confirmation !== "string" || !confirmation.toLowerCase().includes("use my codex reset")) throw new CodexError("Confirmation must contain: use my codex reset"); return await codexMutation(async () => await withDurableAccountLock(workspaceId, id, "reset", async () => { const existing = await db.execute({ sql: "SELECT request_id,state,credit_count,updated_at FROM codex_reset_redemptions WHERE workspace_id=? AND account_id=?", args: [workspaceId, id] }); const prior = existing.rows[0] as unknown as { request_id: string; state: string; credit_count: number | null; updated_at: number } | undefined; if (prior?.state === "completed" && Date.now() - Number(prior.updated_at) < REDEMPTION_IDEMPOTENCY_MS) return; const quota = await quotaForAccount(workspaceId, id, true); if (quota.stale === true || typeof quota.error === "string" || quota.reauthRequired === true || !Number.isFinite(Number(quota.fetchedAt))) throw new CodexError("A fresh Codex quota check is required before redeeming a reset credit.", 502); const weekly = quota.weekly as Record<string, unknown> | null; if (Number(weekly?.usedPercent ?? weekly?.used_percent ?? weekly?.percent_used ?? 0) < 100) throw new CodexError("The weekly Codex quota must be exhausted before redeeming a reset credit."); const credits = Number(quota.unusedResetCredits ?? 0); if (credits < 1) throw new CodexError("No unused Codex reset credits are available."); const requestId = prior?.state === "pending" ? String(prior.request_id) : randomUUID(); if (!prior || prior.state !== "pending") await db.execute({ sql: "INSERT INTO codex_reset_redemptions(workspace_id,account_id,request_id,state,credit_count,created_at,updated_at) VALUES(?,?,?,'pending',?,?,?) ON CONFLICT(workspace_id,account_id) DO UPDATE SET request_id=excluded.request_id,state='pending',credit_count=excluded.credit_count,updated_at=excluded.updated_at", args: [workspaceId, id, requestId, credits, Date.now(), Date.now()] }); const account = await ownLiveAccount(workspaceId, id); const { response, data } = await managementJson<{ status_code?: unknown }>("/v0/management/api-call", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ auth_index: account.authIndex, method: "POST", url: "https://chatgpt.com/backend-api/wham/rate-limit-reset-credits/consume", header: { authorization: "Bearer $TOKEN$", "content-type": "application/json", ...(account.accountId ? { "chatgpt-account-id": account.accountId } : {}) }, data: JSON.stringify({ redeem_request_id: requestId }) }) }); if (!response.ok || Number(data?.status_code) < 200 || Number(data?.status_code) >= 300) throw new CodexError("Codex reset redemption failed.", 502); await db.execute({ sql: "UPDATE codex_reset_redemptions SET state='completed',updated_at=? WHERE workspace_id=? AND account_id=? AND request_id=?", args: [Date.now(), workspaceId, id, requestId] }); await invalidateCodexQuota(workspaceId, id); })); }
